INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('61703986', 61703986, 'analyze_legacy', 'Provinsi DKI Jakarta', 'provinsi', 'PUSAT DATA DAN INFORMASI CIPTA KARYA, TATA RUANG DAN PERTANAHAN', 'Tim Pembangunan, Pengembangan dan Pengelolaan Sistem Informasi Geografis Jakarta Satu - Senior Spatial Data, Development and Education', 'Jasa Konsultansi', 'Seleksi', 'DKI Jakarta, Jakarta Pusat (Kota)', 201300000, 'November 2025', 'APBD', 1, 1, '1 orang/12 bulan', '1. Bertanggung jawab terhadap seluruh pelaksanaan pekerjaan sesuai dengan spesifikasi teknis yang ditetapkan; 2. Membuat jadwal pekerjaan, memberikan tugas sampai dengan memantau dan mengendalikan hasil pekerjaan tim; 3. Melakukan supervisi proses integrasi, mastering, pengolahan, dan pengelolaan data dan informasi spasial ke dalam portal Jakarta Satu; 4. Mengelola akun dan lisensi perangkat lunak GIS (termasuk ArcGIS) serta memastikan tata kelola akses yang aman dan terkendali; 5. Melakukan quality control (QC) terhadap data dan informasi spasial untuk menjamin akurasi, kelengkapan, konsistensi, dan keterbaruan sesuai dengan standarisasi yang telah ditetapkan; 6. Melakukan workshop, sosialisasi, atau pelatihan terkait akuisisi, integrasi, dan pengolahan data geospasial bagi seluruh Perangkat Daerah/Unit Perangkat Daerah di lingkungan Pemerintah Provinsi DKI Jakarta; 7. Merancang dan mengimplementasikan peningkatan integrasi simpul jaringan Jakarta Satu agar data dan layanan terdistribusi secara efisien antar unit; 8. Menyusun pedoman atau panduan teknis pendukung integrasi data dan informasi geospasial; 9. Memberikan dukungan sharing knowledge, mentoring, dan pendampingan teknis penggunaan perangkat lunak GIS serta teknologi pendukungnya. 10. Melaksanakan perumusan konsep dan pelaksanaan kegiatan terkait Jakarta Satu Festival; 11. Membantu penyusunan webinar bicara kota dan list konten publikasi terkait pemanfaatan data geospasial untuk penataan penataan ruang DKI Jakarta. 12. Memastikan seluruh pekerjaan dikerjakan secara efektif dan efisien; 13. Melaksanakan monitoring dan evaluasi internal tim; 14. Melakukan koordinasi dengan tim lain Jakarta Satu untuk pengembangan geospasial Jakarta Satu; 15. Melaporkan dan mempertanggungjawabkan pelaksanaan tugas; 16. Melaporkan dan mempertanggungjawabkan pelaksanaan tugas setiap bulanan dan tahunan; 17. Melaksanakan tugas lainnya yang ditetapkan oleh pimpinan/atasan sesuai kewenangan', 'Tenaga Ahli Muda S1 Pengalaman Minimal 9 Tahun (Jasa Konsultansi Perorangan Non Konstruksi)', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 10122);
INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('61703755', 61703755, 'analyze_legacy', 'Provinsi DKI Jakarta', 'provinsi', 'PUSAT DATA DAN INFORMASI CIPTA KARYA, TATA RUANG DAN PERTANAHAN', 'Tim Pembangunan, Pengembangan dan Pengelolaan Sistem Informasi Geografis Jakarta Satu - Junior Web Developer - 1', 'Jasa Konsultansi', 'Seleksi', 'DKI Jakarta, Jakarta Pusat (Kota)', 122100000, 'November 2025', 'APBD', 1, 1, '1 orang x 12 bulan', '1. Bertanggung jawab terhadap seluruh pelaksanaan pekerjaan sesuai dengan spesifikasi teknis yang ditetapkan; 2. Mengembangkan website geoportal Jakarta Satu dalam bentuk web pages, web application, web map, dan dashboard; 3. Mengembangkan application programming interfaces (APIs) untuk mendukung fungsionalitas website Jakarta Satu; 4. Memberikan dukungan teknis untuk integrasi data dan sistem dengan portal Jakarta Satu; 5. Mengembangkan tools pendukung lainnya dalam sistem Jakarta Satu sesuai dengan kebutuhan; 6. Membuat analisis dan solusi terhadap permasalahan web Jakarta Satu; 7. Menyusun dan menulis dokumentasi pengembangan program; 8. Membantu pelaksanaan Jakarta Satu Festival; 9. Melaporkan dan mempertanggungjawabkan pelaksanaan tugas setiap bulanan dan tahunan; 10. Melaksanakan tugas lainnya yang ditetapkan oleh pimpinan/atasan sesuai kewenangan.', 'Tenaga Ahli Muda S1 Pengalaman Minimal 3 Tahun (Jasa Konsultansi Perorangan Non Konstruksi)', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 10123);
