INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('61704136', 61704136, 'analyze_legacy', 'Provinsi DKI Jakarta', 'provinsi', 'PUSAT DATA DAN INFORMASI CIPTA KARYA, TATA RUANG DAN PERTANAHAN', 'Tim Pembangunan, Pengembangan dan Pengelolaan Sistem Informasi Geografis Jakarta Satu - Team Leader Research and Innovation - 1', 'Jasa Konsultansi', 'Seleksi', 'DKI Jakarta, Jakarta Pusat (Kota)', 161700000, 'November 2025', 'APBD', 1, 1, '1 orang x 12 bulan', '1. Bertanggung jawab terhadap seluruh pelaksanaan pekerjaan sesuai dengan spesifikasi teknis yang ditetapkan; 2. Membuat jadwal pekerjaan, memberikan tugas sampai dengan memantau dan mengendalikan hasil pekerjaan tim; 3. Melakukan supervisi proses eksplorasi pemanfaatan teknologi kecerdasan buatan/geospatial artificial intelligence (Geo AI) untuk pengembangan riset dan analisis spasial; 4. Melakukan supervisi proses pengembangan Peta Dasar 3D Jakarta serta pemanfaatannya untuk pengembangan Peta 3D Jakarta; 5. Melakukan supervisi dalam pemanfaatan data foto udara dan LiDAR baik secara 2D dan 3D; 6. Melakukan pemodelan, simulasi dan analisis spasial tingkat lanjut (contoh: termasuk analisis jaringan, pemodelan aksesibilitas dan analisis pola spasial-temporal) untuk mendukung riset dan berbagai skenario perencanaan kota; 7. Mampu mengembangkan dan mengimplementasikan model Machine Learning dan Deep Learning, serta mengintegrasikan teknologi kecerdasan buatan (AI) untuk eksplorasi dalam pemanfaatan integrasi AI ke dalam analisis spasial; 8. Melaksanakan pengembangan visualisasi informasi geospasial dalam bentuk 3D dan BIM; 9. Menguasai Sistem ArcGIS Portal dan ArcGIS Desktop, pembuatan WebGIS dan Dashboard GIS; 10. Menguasai pengolahan data dalam bentuk spasial dan non spasial (CSV, JSON, XML, SHP, GeoJSON, dan GDB); 11. Membantu integrasi dan melakukan analisis spasial tingkat lanjut terhadap data GIS dari berbagai sumber; 12. Melakukan implementasi perangkat lunak dan data hasil pengembangan riset dan inovasi spasial ke sistem database dan server Jakarta Satu; 13. Mendokumentasikan kegiatan riset dan inovasi, publikasi dan sharing knowledge menjadi sebuah laporan kegiatan; 14. Berkolaborasi dan berkoordinasi dengan tim lain Jakarta Satu untuk implementasi hasil riset GIS ke dalam portal Jakarta Satu. 15. Melaksanakan perumusan konsep dan pelaksanaan kegiatan terkait Jakarta Satu Festival; 16. Memastikan seluruh pekerjaan dikerjakan secara efektif dan efisien; 17. Melaksanakan monitoring dan evaluasi internal tim; 18. Melakukan koordinasi dengan tim lain Jakarta Satu untuk pengembangan geospasial Jakarta Satu; 19. Melaporkan dan mempertanggungjawabkan pelaksanaan tugas; 20. Melaporkan dan mempertanggungjawabkan pelaksanaan tugas setiap bulanan dan tahunan; 21. Melaksanakan tugas lainnya yang ditetapkan oleh pimpinan/atasan sesuai kewenangan.', 'Tenaga Ahli Muda S1 Pengalaman Minimal 5 Tahun (Jasa Konsultansi Perorangan Non Konstruksi)', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 10754);
