INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('61704055', 61704055, 'analyze_legacy', 'Provinsi DKI Jakarta', 'provinsi', 'PUSAT DATA DAN INFORMASI CIPTA KARYA, TATA RUANG DAN PERTANAHAN', 'Tim Pembangunan, Pengembangan dan Pengelolaan Sistem Informasi Geografis Jakarta Satu - Team Leader Spatial Data Development and Education - 1', 'Jasa Konsultansi', 'Seleksi', 'DKI Jakarta, Jakarta Pusat (Kota)', 161700000, 'November 2025', 'APBD', 1, 1, '1 orang/12 bulan', '1. Bertanggung jawab terhadap seluruh pelaksanaan pekerjaan sesuai dengan spesifikasi teknis yang ditetapkan; 2. Membuat jadwal pekerjaan, memberikan tugas sampai dengan memantau dan mengendalikan hasil pekerjaan tim; 3. Melakukan supervisi proses integrasi, mastering, pengolahan, dan pengelolaan manajemen data, analisa data dan metadata data, processing data dan transformasi data dan informasi spasial ke dalam portal Jakarta Satu; 4. Mengelola akun dan lisensi perangkat lunak GIS (termasuk ArcGIS) serta memastikan tata kelola akses yang aman dan terkendali; 5. Melakukan quality control (QC) terhadap data dan informasi spasial untuk menjamin akurasi, kelengkapan, konsistensi, dan keterbaruan sesuai dengan standarisasi yang telah ditetapkan; 6. Melakukan analisa terhadap layanan permintaan data yang ada dalam portal Jakarta Satu; 7. Memahami kebutuhan pengelolaan database yang efektif dan efisien untuk mencapai tujuan perencanaan sistem; 8. Melakukan pengelolaan, penyimpanan dan pengamanan data spasial di Jakarta Satu; 9. Memberikan dukungan workshop, sosialisasi, atau pelatihan terkait akuisisi, integrasi, dan pengolahan data geospasial bagi seluruh Perangkat Daerah/Unit Perangkat Daerah di lingkungan Pemerintah Provinsi DKI Jakarta; 10. Membantu melakukan integrasi sistem GIS dengan sistem eksternal melalui REST API dan Web Service; 11. Mengimplementasikan arsitektur data dan model data untuk mendukung tim dalam membuat dan mengembangkan sistem informasi geografis; 12. Mengimplementasikan struktur data KUGI dan standarisasi lain yang ditetapkan pada data Jakarta Satu; 13. Melakukan monitoring seluruh data di Jakarta Satu; 14. Mendukung pelaksanaan SDI di tingkat provinsi; 15. Merancang dan mengimplementasikan peningkatan integrasi simpul jaringan Jakarta Satu agar data dan layanan terdistribusi secara efisien antar unit; 16. Memberikan dukungan sharing knowledge, mentoring, dan pendampingan teknis penggunaan perangkat lunak GIS serta teknologi pendukungnya. 17. Membantu Melaksanakan perumusan konsep dan pelaksanaan kegiatan terkait Jakarta Satu Festival; 18. Memastikan seluruh pekerjaan dikerjakan secara efektif dan efisien; 19. Melaksanakan monitoring dan evaluasi internal tim; 20. Melakukan koordinasi dengan tim lain Jakarta Satu untuk pengembangan geospasial Jakarta Satu; 21. Melaporkan dan mempertanggungjawabkan pelaksanaan tugas; 22. Melaporkan dan mempertanggungjawabkan pelaksanaan tugas setiap bulanan dan tahunan; 23. Melaksanakan tugas lainnya yang ditetapkan oleh pimpinan/atasan sesuai kewenangan', 'Tenaga Ahli Muda S1 Pengalaman Minimal 5 Tahun (Jasa Konsultansi Perorangan Non Konstruksi)', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 10931);
