INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('61850013', 61850013, 'analyze_legacy', 'Provinsi DKI Jakarta', 'provinsi', 'DINAS PERPUSTAKAAN DAN KEARSIPAN', 'Penyediaan Jasa Tenaga Ahli Publikasi Media Kameraman', 'Jasa Konsultansi', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Timur (Kota)', 61050000, 'December 2025', 'APBD', 1, 1, '1 Orang x 6 Bulan', '1) Mengoperasikan kamera untuk pengambilan dokumentasi baik berupa video maupun gambar untuk kegiatan-kegiatan pembudayaan kegemaran membaca, mencakup: - pengambilan stockshoot berkaitan dengan benchmark kota Jakarta, baik secara pariwisata, perbukuan, dan lain sebagainya; - konten media sosial semester 1; - kegiatan literasi bersama komunitas; dan - kegiatan-kegiatan pembudayaan kegemaran membaca semester 1. 2) Bertanggung jawab terhadap kualitas foto dan pengerjaannya (editing foto, distribusi foto dan pekerjaan fotografi lainnya). 3) Bertanggung jawab untuk pemeliharaan kamera dan peralatan pendukung dokumentasi lainnya. 4) Melakukan pengelolaan database untuk dokumentasi yang dapat diakses dengan baik. 5) Melakukan tugas-tugas lain sesuai penugasan yang berkaitan dengan ruang lingkup publikasi pembudayaan kegemaran membaca. 6) Memberikan laporan rekap bentuk dan jumlah foto dan video yang diproduksi kepada koordinator publikasi pembudayaan kegemaran membaca. 7) Memberikan laporan kinerja kepada Subkelompok Pengembangan Pembudayaan Kegemaran Membaca dengan diketahui/persetujuan Kepala Bidang Pengembangan Perpustakaan dan Pembudayaan Kegemaran Membaca.', 'Sesuai dengan KAK', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 11474);
