INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62713613', 62713613, 'analyze_legacy', 'Provinsi Jawa Barat', 'provinsi', 'Dinas Komunikasi dan Informatika', 'Pengembangan dan Pemeliharaan Aplikasi Khusus (PLDDIG)', 'Jasa Lainnya', 'E-Purchasing', 'Jawa Barat, Bandung (Kota)', 2597385000, 'January 2026', 'APBD', 1, 1, '4 Paket', 'Ruang Lingkup pekerjaan yang akan dilakukan, dapat disesuaikan dengan kebutuhan riil pengembangan dan pemeliharaan aplikasi, dengan ruang lingkup sebagai berikut : 1. Pemeliharaan adaptif; 2. Pemeliharaan korektif; 3. Pemeliharaan preventif; 4. Pengembangan perfektif tanpa penambahan fungsi/fitur; 5. Pengembangan perfektif dengan penambahan fungsi/fitur, khusus untuk aplikasi Sapawarga dan Hotline Jabar. Adapun rincian aktivitas pengembangan dan pemeliharaan yang dilakukan antara lain sebagai berikut : 1. Aktivitas Software Programming 2. Aktivitas Site Reliability Engineering 3. Aktivitas Software Project Management 4. Aktivitas System Analysis 5. Aktivitas Pendukung : • Perjalanan Dinas ke Luar Kota Jika Diperlukan (Transportasi dan Akomodasi Difasilitasi). • Survey Lapangan di Dalam Kota. • Penyusunan dan Pemeliharaan Buku Panduan dan Dokumen Teknis Aplikasi (Soft Copy). • Rapat Koordinasi dan Konsolidasi dengan Stakeholder (Ruangan dan Mamin Difasilitasi). • Pelatihan, Sosialisasi dan Diseminasi kepada Pengguna (Ruangan dan Mamin Difasilitasi). • Transfer Knowledge (Ruangan Difasilitasi). • Aktivitas Harian di Ruang Kerja (Ruang Kerja Difasilitasi).', '1. Pengembangan dan Pemeliharaan aplikasi khusus layanan publik yang dikelola oleh UPTD PLDDIG, dengan spesifikasi teknis dapat mencakup aplikasi-aplikasi sebagai berikut: a. Aplikasi Sapawarga; b. Aplikasi Portal Jabar; c. Aplikasi Hotline Jabar; d. Aplikasi Jabar Istimewa Digital Academy; e. Aplikasi J-Site. 2. Platform dan Kompatibilitas a. Web Based; b. Mobile Responsive; c. Mobile Application. 3. Hak Akses dan Kepemilikan a. Seluruh kode sumber (source code), modifikasi kode sumber (source code), akun / akses aplikasi, serta dokumentasi menjadi hak milik penuh Pemerintah Daerah Provinsi Jawa Barat; b. Hak Kekayaan Intelektual (HAKI) adalah milik Pemerintah Daerah Provinsi Jawa Barat.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 12123);
