INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62674055', 62674055, 'analyze_legacy', 'Provinsi Jawa Barat', 'provinsi', 'Badan Pendapatan Daerah', 'Belanja Jasa Petugas Front Office, Pramubakti dan Pengemudi P3DW Kota Bandung I Pajajaran', 'Jasa Lainnya', 'E-Purchasing', 'Jawa Barat, Bandung (Kota)', 463457092, 'December 2025', 'APBD', 1, 1, '1 paket', 'Jumlah Petugas Front Office sebanyak 2 orang, Petugas Pramubakti sebanyak 1 orang, Petugas Pengemudi sebanyak 3 orang 1. Front Office memberikan layanan penerimaan tamu, mengelola informasi dasar, mengatur buku tamu, menangani panggilan telepon, serta menjaga kerapian area pelayanan untuk memastikan proses pelayanan publik berjalan ramah dan tertib; 2. Pramubakti mendukung tugas operasional kantor seperti penataan ruang rapat, penyajian minuman, pengiriman dokumen internal, menjaga kerapian area umum, serta membantu kebutuhan kegiatan kantor sehari-hari. 3. Supir/Pengemudi melaksanakan tugas mengoperasikan kendaraan dinas, melakukan pengecekan rutin kendaraan, menjaga kebersihan kendaraan, mengantar/menjemput sesuai penugasan, serta memastikan kendaraan selalu siap dan aman digunakan', '1. Front Office Spesifikasi Kinerja/Mutu: Pelayanan tamu yang ramah, cepat, dan rapi di area front desk. Indikator Kinerja: Tamu terlayani baik, pencatatan rapi, area layanan selalu tertata. 2. Pramubakti Spesifikasi Kinerja/Mutu: Mendukung operasional kantor seperti penataan ruang rapat dan penyajian minuman. Indikator Kinerja: Ruang rapat siap sebelum digunakan, pelayanan minuman tepat waktu, dan area umum rapi. 3. Supir Pengemudi Spesifikasi Kinerja/Mutu: Kendaraan dinas selalu siap, bersih, dan aman digunakan. Indikator Kinerja: Tepat waktu, aman berkendara, dan kendaraan dalam kondisi layak pakai.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 12448);
