INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62035599', 62035599, 'analyze_legacy', 'Provinsi DKI Jakarta', 'provinsi', 'DINAS CIPTA KARYA, TATA RUANG DAN PERTANAHAN', 'Pengadaan Tenaga Jasa Lainnya Perorangan Pengelolaan Kegiatan Kesekretariatan - Pengolah Data Perpajakan dan Keuangan', 'Jasa Lainnya', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Pusat (Kota)', 90090000, 'December 2025', 'APBD', 1, 1, '1 Orang x 12 Bulan', 'Pengadaan Tenaga Jasa Lainnya Perorangan Pengelolaan Kegiatan Kesekretariatan - Pengolah Data Perpajakan dan Keuangan', '1. Pendidikan minimal S1 Akuntansi dengan IPK minimal 3,5 2. Memiliki Sertifikat Pajak Brevet A dan B 3. Pengalaman Minimal 3 (tiga) Tahun dalam bidang pengolahan data perpajakan dan keuangan 4. Memiliki Nomor Induk Berusaha (NIB) dengan Klasifikasi Baku Lapangan Usaha Indonesia (KBLI) 96990 5. Memiliki pemahaman yang mendalam mengenai perpajakan 6. Mampu melakukan pengolahan data perpajakan dan menyajikan data yang komprehensif 7. Memiliki pengalaman dalam menyusun Laporan Perpajakan Pemerintah/BUMN/ BUMD 8. Memiliki integritas tinggi dan menjunjung tinggi kode etik profesional dalam setiap pelaksanaan tugas 9. Memiliki pengalaman paling kurang 1 (satu) pekerjaan dalam kurun waktu 2 (dua) tahun terakhir di lingkungan Pemerintah/ BUMN/BUMD sebagai pengolah data perpajakan dan keuangan. 10. Memiliki nilai pekerjaan sejenis tertinggi dalam sejenis tertinggi dalam kurun waktu 3 (tiga) tahun terakhir paling kurang sama dengan 50% (lima puluh persen) nilai total HPS;', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 12637);
