INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('61756181', 61756181, 'analyze_legacy', 'Provinsi DKI Jakarta', 'provinsi', 'PUSAT DATA DAN INFORMASI CIPTA KARYA, TATA RUANG DAN PERTANAHAN', 'Tim Pembangunan, Pengembangan dan Pengelolaan Sistem Informasi Geografis Jakarta Satu - Junior Spatial Researcher For Spatial Development - 3', 'Jasa Konsultansi', 'Seleksi', 'DKI Jakarta, Jakarta Pusat (Kota)', 122100000, 'November 2025', 'APBD', 1, 1, '1 orang x 12 bulan', '1. Bertanggung jawab terhadap seluruh pelaksanaan pekerjaan sesuai dengan spesifikasi teknis yang ditetapkan; 2. Membantu proses eksplorasi pemanfaatan Teknologi kecerdasan buatan / Geospatial Artificial Intelligence (Geo AI) untuk pengembangan riset dan analisis spasial sesuai arahan team leader/senior; 3. Membantu proses pengembangan Peta Dasar 3D Jakarta serta pemanfaatannya untuk pengembangan Peta 3D Jakarta sesuai arahan team leader/senior; 4. Membantu pemanfaatan data foto udara dan LiDAR baik secara 2D dan 3D untuk riset dan inovasi sesuai arahan team leader/senior; 5. Membantu analisis spasial untuk mendukung riset dan berbagai skenario perencanaan kota sesuai arahan team leader/senior; 6. Membantu pengembangan pemanfaatan integrasi AI ke dalam analisis spasial sesuai arahan team leader/senior; 7. Membantu pengembangan visualisasi informasi geospasial dalam bentuk 3D dan BIM sesuai arahan team leader/senior; 8. Membantu integrasi dan melakukan analisis spasial tingkat lanjut terhadap data GIS dari berbagai sumber sesuai arahan team leader/senior; 9. Membantu implementasi perangkat lunak dan data hasil pengembangan riset dan inovasi spasial ke sistem database dan server Jakarta Satu sesuai arahan team leader/senior; 10. Membuat dan mendokumentasikan kegiatan riset dan inovasi, publikasi dan sharing knowledge menjadi sebuah laporan kegiatan; 11. Berkolaborasi dan berkoordinasi dengan tim lain Jakarta Satu untuk implementasi hasil riset GIS ke dalam portal Jakarta Satu. 12. Membantu perumusan konsep dan pelaksanaan kegiatan terkait Jakarta Satu Festival; 13. Memastikan seluruh pekerjaan dikerjakan secara efektif dan efisien; 14. Melakukan koordinasi dengan tim lain Jakarta Satu untuk pengembangan geospasial Jakarta Satu; 15. Melaporkan dan mempertanggungjawabkan pelaksanaan tugas; 16. Melaporkan dan mempertanggungjawabkan pelaksanaan tugas setiap bulanan dan tahunan; 17. Melaksanakan tugas lainnya yang ditetapkan oleh pimpinan/atasan sesuai kewenangan', 'Tenaga Ahli Muda S1 Pengalaman Minimal 3 Tahun (Jasa Konsultansi Perorangan Non Konstruksi)', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 13069);
