INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62337875', 62337875, 'analyze_legacy', 'Kota Semarang', 'kabkota', 'BADAN PENGELOLAAN KEUANGAN DAN ASET DAERAH', 'Belanja Jasa Tenaga Keamanan', 'Jasa Lainnya', 'E-Purchasing', 'Jawa Tengah, Semarang (Kota)', 537634800, 'December 2025', 'APBD', 1, 1, '1 Paket', 'Belanja Jasa Tenaga Keamanan', '1. Warga Negara Indonesia (TKDN 100%); 2. Jenis kelamin laki-laki; 3. Berusia minimal 18 Tahun maksimal 40 Tahun; 4. Tinggi pria minimal 167 Cm; 5. Pendidikan minimal Sekolah Menengah Umum atau sederajat; 6. Menyertakan Surat Keterangan Catatan Kepolisian; 7. Lulus tes kesehatan; 8. Memiliki sertifikasi satpam minimal Gada Pratama; 9. Memiliki pengalaman sebagai satpam minimal 1 tahun. Spesifikasi Pelayanan tenaga keamanan yang dibutuhkan dalam kegiatan adalah : 1. Menjaga dan mengawasi asset-asset Pemerintah di gudang dan gedung BPKAD Kota Semarang; 2. Memberikan himbauan protokol kesehatan kepada pengunjung di Gudang dan gedung kantor BPKAD Kota Semarang; 3. Memberikan himbauan tentang peraturan yang diberlakukan di Gudang dan gedung kantor BPKAD Kota Semarang; 4. Melaksanakan keamanan kegiatan oleh BPKAD Kota Semarang; 5. Jika sewaktu-waktu ada perubahan jam kerja yang diperintahkan oleh BPKAD Kota Semarang maka penyedia jasa wajib melaksanakan; 6. Melakukan pengawalan/pengamanan kepada tamu Pemerintah Kota Semarang dan asset Pemerintah Kota Semarang; 7. Melaksanakan patroli keamanan bersama di gudang dan gedung kantor BPKAD Kota Semarang 8. Kemampuan penyidikan dan penyelidikan setiap kejadian harus dimiliki oleh setiap personil sebelum ditangani oleh pihak yang berwajib, supaya dapat mengantisipasi sebelum hal-hal terjadi; 9. Melakukan pencegahan kejahatan di Gudang dan gedung kantor BPKAD Kota Semarang dengan berkoordinasi dengan pihak-pihak terkait; 10. Mengamankan pelaku dan serta barang bukti, dapat meminta saksi-saksi yang benar mengetahui kejadian dan wajib menjadi saksi apabila personil tersebut mengetahui kejadian tersebut; 11. Membuat laporan kepada BPKAD Kota Semarang setiap pagi dan malam serta melaporkan segala sesuatu yang terjadi segera untuk dilaporkan kepada BPKAD Kota Semarang dalam bentuk buku laporan dan dokumentasi; 12. Penyedia jasa wajib melaporkan dan mengganti personil anggota apabila ada anggota/personil yang menyalahi/melanggar aturan yang telah disepakati atau kinerja anggota/personil dianggap kurang mampu oleh BPKAD Kota Semarang.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 13739);
