INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('61768168', 61768168, 'analyze_legacy', 'Provinsi DKI Jakarta', 'provinsi', 'UNIT PENGELOLA RUMAH SUSUN III', 'Penyediaan Jasa Tenaga Pelayanan Umum - Customer Relation Officer', 'Jasa Lainnya', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Utara (Kota)', 531361350, 'December 2025', 'APBD', 1, 1, '8 Orang', 'a. Mampu menampung kritik dan saran dari customer; b. Menginformasikan dan mensosialisasikan peraturan penghunian Rumah Susun dan Program-program UPRS; c. Mampu memberikan pembinaan kemasyarakatan kepada penghuni Rumah Susun; d. Mampu melakukan analisa kebutuhan warga penghuni program pemberdayaan masyarakat dan pendampingan pelaksanaan program pemberdayaan dari SKPD/UKPD atau CSR; e. Kompeten dalam hal melakukan verifikasi/pemeriksaan administrasi kelengkapan berkas customer; f. Menerima tanda bukti dan penyerahan dokumen customer, dan menyerahkan kembali dokumen yang dibutuhkan customer; g. Bersedia menjadi tempat informasi bagi para customer yang bertanya; h. Mampu melakukan identifikasi, pengelolaan dan pendataan warga rusun; i. Bersedia mendampingi pelaksanaan kegiatan pemberdayaan warga rusun; j. Mampu menjadi mediator pihak yang melakukan kerja sama promosi; k. Bersedia membantu pengelolaan kerja sama promosi; l. Kompeten dalam mengelola website; m. Mampu merekap catatan harian; n. Mampu merekap laporan bulanan; dan o. Bersedia melaksanakan tugas-tugas lain yang diberikan oleh Kepala UPRS dan Para Aparatur Sipil Negara (ASN).', '1. Pendidikan minimal D3; 2. Mahir mengoperasikan Ms. Office (MS Word, Excel, Power Point dll); 3. Diutamakan memiliki sertifikat pelatihan/bimbingan teknis terkait pengoperasian komputer/administrasi kontrak; 4. Diutamakan berpengalaman di Bidangnya yaitu Administrasi Pelayanan Umum Kantor di Lingkungan Pemerintah Provinsi DKI Jakarta minimal selama 2 (dua) tahun.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 16259);
