INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('61774582', 61774582, 'analyze_legacy', 'Provinsi DKI Jakarta', 'provinsi', 'SUKU DINAS TENAGA KERJA, TRANSMIGRASI, DAN ENERGI KOTA ADMINISTRASI JAKARTA UTARA', 'Penyediaan Jasa PJLP Petugas Keamanan', 'Jasa Lainnya', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Utara (Kota)', 841894716, 'November 2025', 'APBD', 1, 1, '12 Orang', 'Lingkup pekerjaan yang akan dilaksanakan oleh PJLP Petugas Keamanan, antara lain: Melaksanakan pengamanan secara menyeluruh di lokasi kerja. Melaksanakan tugas dan fungsi sesuai dengan penempatan di lokasi masing-masing. Penjagaan di Pos Satpam, pintu masuk dan keluar, lobby gedung, setiap lantai serta seluruh area lingkungan kantor; Melakukan pemeriksaan pada tamu yang akan masuk ke area kerja. Menahan KTP/SIM setiap tamu yang akan memasuki area kerja dan mengisi buku tamu. Memeriksa setiap mobil/motor yang masuk atau keluar. Khusus untuk mobil bak terbuka/tertutup harus diperiksa muatan dan surat jalan. Penjagaan Pos/Titik penjagaan harus berputar/berganti dengan Pos/Titik penjagaan terdekat setiap jam, contoh Anggota Pos 1 menduduki Pos 2, Pos 2 menduduki Pos 3 dan seterusnya. Melaporkan setiap saat melalui HT keadaan sekitar atau situasi ke Posko. Penggeseran anggota dilaporkan ke Posko dari masing-masing Pos 1 sampai dengan Pos 3, begitupun sebaliknya. Posko memonitor setiap saat keadaan/situasi di Pos 1 sampai dengan 3. Menjaga dan memelihara asset dan inventaris Kantor Tempat Bekerja. Menertibkan parkir mobil dan motor pada saat berada di area gedung kantor. Anggota bertanggung jawab atas tugas dan fungsi selama melaksanakan tugas. Dilarang melakukan penggeseran waktu tugas, pagi ke malam atau sebaliknya secara sendiri-sendiri. Mencatat keadaan, situasi, kejadian kedalam buku laporan. Melakukan serah terima piket yang lama kepada piket yang baru Melaksanakan disposisi atasan atau tugas lain yang diperlukan.', 'Usia minimal 18 tahun dan maksimal 55 tahun Pendidikan minimal SMA/SMK sederajat Memiliki sertifikat dan KTA Gada Pratama Memiliki pengalaman kerja sebagai petugas keamanan Sehat Jasmani dan rohani Bebas Narkoba', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 16477);
