INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('61774702', 61774702, 'analyze_legacy', 'Kementerian Perencanaan Pembangunan Nasional', 'central', 'KANTOR MENTERI NEGARA PPN  BAPPENAS', 'TENAGA AHLI MANAJEMEN (MANAGEMENT SPECIALIST) PADA SEKRETARIAT PERCEPATAN PENURUNAN STUNTING HIBAH INEY KEMENTERIAN PPN/BAPPENAS', 'Jasa Konsultansi', 'Seleksi', 'DKI Jakarta, Jakarta Pusat (Kota)', 1120000000, 'November 2025', 'APBN - HIBAH LANGSUNG LUAR NEGERI (K)', 0, 1, '32 Bulan', 'Ruang lingkup Tenaga Ahli Management (Management Specialist) dalam penugasan adalah: 1. Mengoordinasikan serta melakukan supervisi aspek teknis administrasi dan manajerial dalam sekretariat percepatan penurunan stunting di Kementerian PPN/Bappenas, mencakup: a. Pelaksanaan proses pengadaan; b. Penyusunan rencana kerja dan anggaran; c. Pengawalan kinerja anggaran; dan d. Penyiapan dan pengawalan proses audit. 2. Mengawal dan mengoordinasikan kegiatan terkait administrasi dan keuangan kegiatan dalam lingkup tugas sebagai PIU maupun PMU. 3. Mengawal aspek administrasi dan tata kelola keuangan dalam penyusunan serta pelaksanaan rencana kegiatan dan anggaran seluruh PIU maupun beneficiaries. 4. Memastikan setiap aspek administrasi dan keuangan sesuai dengan peraturan yang berlaku di sisi pemerintah maupun Bank Dunia, sejak proses Perencanaan hingga pelaporan dan audit. 5. Menjalankan penugasan lain sesuai arahan dari pimpinan.', 'Posisi ini ditujukan kepada individu Warga Negara Indonesia professional dan bukan ASN atau anggota TNI/Polri, serta memiliki penguasaan di bidang kesehatan, gizi, sosial, manajemen, atau bidang lain yang relevan khususnya pada manajemen proyek dan Untuk posisi ini dibutuhkan tenaga ahli dengan latar belakang pendidikan diutamakan Sarjana (S1) di bidang manajemen, administrasi perkantoran, atau akuntansi.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 17246);
