INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('61764781', 61764781, 'analyze_legacy', 'Provinsi DKI Jakarta', 'provinsi', 'UNIT PENGELOLA RUMAH SUSUN III', 'Penyediaan Jasa Petugas Keamanan', 'Jasa Lainnya', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Utara (Kota)', 9050368197, 'December 2025', 'APBD', 1, 1, '130 Orang', '1. Menjaga dan memelihara keamanan dan ketertiban di lingkungan Rusunawa; 2. Melakukan koordinasi dengan instansi terkait dalam rangka menunjang keamanan dan ketertiban di lingkungan Rusunawa; 3. Mengambil langkah preventif dan represif (apabila diperlukan) dalam hal terjadi upaya dari pihak luar yang dapat menganggu keamanan dan ketertiban di lingkungan Rusunawa; 4. Mendampingi dan/atau orang dalam melakukan pendataan, inspeksi mendadak, dan/atau penertiban; 5. Menjaga aset dan fasilitas yang tidak terbatas pada gedung dan sarana penunjang lainya di Rusunawa dari tindakan pencurian oleh pihak-pihak yang tidak bertanggung jawab; 6. Mencegah terjadinya pelanggaran atas Tata Tertib Rusunawa yang dilakukan oleh warga penghuni Rusunawa (misalnya merubah struktur bangunan, memelihara hewan, dan penghunian tanpa legalitas yang sah); 7. Memberikan pelayanan prima kepada warga penghuni Rusunawa; 8. Membuat laporan harian hasil pekerjaan kepada Pejabat Pembuat Komitmen (PPK) sebagai perpanjangan tangan Unit Pengelola Rumah Susun III ; 9. Melakukan pengecekan terhadap pihak-pihak yang bukan termasuk penghuni Rusunawa ketika memasuki area Rusunawa; 10. Mengatur dan mengambil langkah yang diperlukan untuk mengatur penempatan kendaraan di area Rusunawa; dan 11. Melaksanakan tugas-tugas lain yang diberikan oleh Kepala UPRS Lain dan para Aparatur Sipil Negara (ASN).', '1. Pendidikan minimal SLTP/Sederajat ; 2. Diutamakan bagi yang memiliki sertifikat Pelatihan Keamanan yang dikeluarkan oleh lembaga terkait dan masih aktif; dan 3. Diutamakan berpengalaman dibidangnya, di Lingkungan Pemerintah Provinsi DKI Jakarta minimal 1 tahun.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 18293);
