INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62670608', 62670608, 'analyze_legacy', 'Kab. Sidoarjo', 'kabkota', 'Badan Pelayanan Pajak Daerah', 'Belanja Spanduk - PDL', 'Jasa Lainnya', 'E-Purchasing', 'Jawa Timur, Sidoarjo (Kab.)', 9990000, 'May 2026', 'APBD', 1, 1, '30 Buah', 'Uraian pekerjaan Pengadaan Spanduk Ukuran Minimal 1 x 5 meter ini meliputi kegiatan perencanaan desain, pencetakan, penyediaan, pengiriman, dan penyerahan spanduk yang digunakan sebagai media informasi, sosialisasi, dan publikasi kegiatan pemerintah daerah. Pekerjaan ini mencakup penyediaan spanduk dengan kualitas bahan dan hasil cetak yang baik, tahan terhadap kondisi luar ruangan (outdoor), serta memiliki tampilan visual yang jelas dan mudah dibaca. Spanduk yang disediakan harus sesuai dengan ukuran minimal yang ditetapkan serta memenuhi spesifikasi teknis yang dipersyaratkan. Ruang lingkup pekerjaan meliputi: Penyediaan spanduk dengan ukuran minimal 1 x 5 meter sesuai kebutuhan dan desain yang ditentukan. Pencetakan spanduk berdasarkan materi, teks, logo, dan konten yang disediakan oleh pihak pengguna. Penggunaan bahan spanduk yang kuat, tidak mudah robek, dan tahan terhadap cuaca. Pemasangan mata ayam (ring) atau penguat pada sisi-sisi spanduk untuk memudahkan pemasangan. Penyelesaian dan pengepakan spanduk secara rapi dan aman. Pengiriman dan penyerahan spanduk ke lokasi yang ditentukan oleh Pejabat Pembuat Komitmen (PPK) atau Pejabat Pengadaan tepat waktu. Penggantian spanduk apabila terdapat cacat cetak, kerusakan, atau ketidaksesuaian ukuran dan desain pada saat pemeriksaan. Pelaksanaan pemeriksaan dan serah terima barang yang dituangkan dalam Berita Acara Serah Terima (BAST). Dengan terlaksananya pekerjaan ini, diharapkan ketersediaan media informasi berupa spanduk dapat mendukung kegiatan sosialisasi dan penyampaian informasi kepada masyarakat secara efektif dan efisien.', 'Spesifikasi Teknis Pengadaan Spanduk dengan Ukuran Minimal 1 x 5 Meter 1. Nama Barang Spanduk 2. Fungsi Sebagai media informasi, sosialisasi, dan publikasi kegiatan pemerintah daerah. 3. Ukuran Minimal 1 x 5 meter Toleransi ukuran ± 2 cm 4. Bahan Flexi banner / vinyl banner Ketebalan minimal 280 – 340 gsm Tahan air dan tahan cuaca (outdoor) 5. Warna Full color (CMYK) Warna tajam dan tidak mudah pudar 6. Metode Cetak Digital printing resolusi tinggi Hasil cetak jelas, tidak pecah, dan tidak blur 7. Desain Desain sesuai materi yang diberikan oleh pengguna Memuat teks, logo, dan informasi kegiatan sesuai kebutuhan Tata letak rapi dan mudah dibaca dari jarak tertentu 8. Finishing Dijahit/di-press pada sisi spanduk Dilengkapi mata ayam (ring) pada setiap sudut dan jarak tertentu Tepi rapi dan kuat 9. Kualitas Produk Tidak sobek Tidak luntur saat terkena air Tidak terdapat cacat cetak (bercak, garis, atau warna tidak merata) 10. Jumlah Sesuai kebutuhan dan tercantum dalam kontrak atau surat pesanan 11. Pemasangan Dikirim dan dipasang ke lokasi yang ditentukan oleh Pejabat Pembuat Komitmen (PPK) Tepat waktu sesuai jadwal yang ditetapkan 12. Pemeriksaan dan Serah Terima Dilakukan pemeriksaan kesesuaian ukuran, bahan, dan hasil cetak Barang yang tidak sesuai spesifikasi wajib diganti Serah terima dituangkan dalam Berita Acara Serah Terima (BAST) 13. Garansi Garansi penggantian apabila terdapat cacat produksi atau ketidaksesuaian spesifikasi', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 18855);
