INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('61774612', 61774612, 'analyze_legacy', 'Kementerian Perencanaan Pembangunan Nasional', 'central', 'KANTOR MENTERI NEGARA PPN  BAPPENAS', 'DEPUTI MANAJER PROJECT IMPLEMENTING UNIT PADA SEKRETARIAT PERCEPATAN PENURUNAN STUNTING HIBAH INEY KEMENTERIAN PPN/BAPPENAS', 'Jasa Konsultansi', 'Seleksi', 'DKI Jakarta, Jakarta Pusat (Kota)', 1600000000, 'November 2025', 'APBN - HIBAH LANGSUNG LUAR NEGERI (K)', 0, 1, '32 Bulan', 'Ruang lingkup tenaga Deputi Manajer PIU dalam penugasan adalah: 1. Mengoordinasikan pelaksanaan tugas Kementerian PPN/Bappenas sebagai PIU dengan unit-unit internal di Kementerian PPN/Bappenas, lintas kementerian/lembaga, dan lender (Bank Dunia). 2. Menyusun usulan rencana kegiatan dan anggaran Kementerian PPN/ Bappenas sebagai PIU. 3. Melaksanakan komunikasi dan advokasi yang efektif dengan kementerian/lembaga, pemerintah daerah, donor, organisasi masyarakat, lembaga swadaya masyarakat, forum lembaga penelitian/ pakar/akademisi/mahasiswa, mitra pembangungan, swasta, dan media. 4. Mengoordinasikan penyusunan serta pelaksanaan rencana kegiatan dan anggaran seluruh tenaga ahli agar saling terintegrasi dan mendukung dalam mencapai disbursement linked indicator (DLI) dan output Bappenas. 5. Memastikan sinkronisasi dan supervisi pelaksanaan kegiatan dan output kegiatan masing-masing komponen dalam lingkup sekretariat. 6. Mengoordinasikan dan melakukan supervisi atas pelaksanaan tugas seluruh tenaga ahli yang terkait dengan fungsi Bappenas sebagai PIU Program Hibah INEY. 7. Menyusun laporan kegiatan dan capaian output seluruh tenaga ahli dalam rangka mendukung pencapaian DLI dan pelaksanaan tugas Bappenas terkait penurunan stunting, untuk disampaikan kepada manajer program dan pimpinan (jika diperlukan). 8. Memberikan dukungan pelaksanaan tugas Kementerian PPN/Bappenas dalam fungsi koordinasi perencanaan, penganggaran, pemantauan dan evaluasi dalam penurunan stunting melalui output yang dihasilkan oleh tenaga ahli. 9. Menyiapkan analisis, melakukan debottlenecking, dan memberikan arahan terkait progres pencapaian DLI di setiap komponen dan kegiatan yang dilaksanakan tenaga ahli. 10. Mengoordinasikan output tenaga ahli dalam kegiatan diseminasi hasil keluaran dan/atau publikasi laporan yang dihasilkan sekretariat melalui knowledge management system yang terpadu. 11. Melakukan monitoring pelaksanaan percepatan penurunan stunting sesuai Perpres Nomor 72 tahun 2021.', 'Posisi ini ditujukan kepada individu Warga Negara Indonesia professional dan bukan ASN atau anggota TNI/Polri, serta memiliki penguasaan di bidang kesehatan, gizi, sosial, manajemen, atau bidang lain yang relevan khususnya pada manajemen proyek. dan Untuk posisi ini dibutuhkan tenaga ahli dengan latar belakang pendidikan diutamakan Master (S2) di bidang manajemen, sosial, kesehatan, gizi, ekonomi, ilmu pembangunan, atau bidang lain yang relevan.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 19064);
